<script lang="ts">
 import WeatherIcon from './WeatherIcon.svelte';
 import {celsius,weatherKind,finiteReading} from './weather.mjs';
 let {days,payload,view,selected=$bindable('')}:{days:any[],payload:any,view:string,selected?:string}=$props();
 const key=(dt:number)=>new Date(dt*1000).toLocaleDateString('sv-SE',{timeZone:'Africa/Harare'});
 let active=$derived(days.find(d=>key(d.timestamp)===selected)||days[0]);
 let hourly=$derived((payload?.normal?.hourly||payload?.hourly||[]).filter((h:any)=>Number.isFinite(h?.dt)&&active&&key(h.dt)===key(active.timestamp)));
 let month=$state('');
 let monthKey=$derived(month||key(days[0].timestamp).slice(0,7));
 let cells=$derived.by(()=>{const [y,m]=monthKey.split('-').map(Number);const offset=(new Date(Date.UTC(y,m-1,1)).getUTCDay()+6)%7,count=new Date(Date.UTC(y,m,0)).getUTCDate();return Array.from({length:Math.ceil((offset+count)/7)*7},(_,i)=>i<offset||i>=offset+count?null:{day:i-offset+1,key:monthKey+'-'+String(i-offset+1).padStart(2,'0')});});
 function move(n:number){const [y,m]=monthKey.split('-').map(Number);month=new Date(Date.UTC(y,m-1+n,1)).toISOString().slice(0,7);}
 const value=(n:number|null,suffix:string)=>n===null?'Unavailable':Math.round(n)+suffix;
</script>
{#if view==='daily'}
 <section class="period-panel"><div class="period-heading"><div><p class="p-kicker">DAILY / HOURLY DETAIL</p><h2>Daily forecast</h2></div><label>Forecast day<select value={selected||key(days[0].timestamp)} onchange={e=>selected=e.currentTarget.value}>{#each days as d}<option value={key(d.timestamp)}>{new Date(d.timestamp*1000).toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'short',timeZone:'Africa/Harare'})}</option>{/each}</select></label></div>
 {#if hourly.length}<div class="hours">{#each hourly as h}<article><strong>{new Date(h.dt*1000).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'Africa/Harare'})}</strong><div class="icon"><WeatherIcon kind={weatherKind(h.weather?.[0])}/></div><b>{value(celsius(h.temp),'°C')}</b><span>{h.weather?.[0]?.description||'Forecast'}</span><small>Rain chance {value(finiteReading(h.pop,0,1)===null?null:h.pop*100,'%')}</small><small>Wind {value(finiteReading(h.wind_speed,0),' m/s')}</small></article>{/each}</div>
 {:else}<div class="daily-summary"><div class="icon"><WeatherIcon kind={active?.icon}/></div><div><h3>{active?.description}</h3><strong>{value(active?.max??null,'°C')} high / {value(active?.min??null,'°C')} low</strong><p>Hourly detail is unavailable for this day.</p></div></div>{/if}</section>
{:else if view==='monthly'}
 <section class="period-panel"><div class="period-heading"><div><p class="p-kicker">MONTHLY / FORECAST CALENDAR</p><h2>{new Date(monthKey+'-01T12:00:00Z').toLocaleDateString('en-GB',{month:'long',year:'numeric',timeZone:'Africa/Harare'})}</h2></div><div class="month-buttons"><button type="button" class="p-button subtle" onclick={()=>move(-1)} aria-label="Previous month">←</button><button type="button" class="p-button subtle" onclick={()=>month=''}>Forecast month</button><button type="button" class="p-button subtle" onclick={()=>move(1)} aria-label="Next month">→</button></div></div><p class="coverage">{days.filter(d=>key(d.timestamp).startsWith(monthKey)).length} of {cells.filter(Boolean).length} days have forecast data available.</p><div class="calendar">{#each ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as d}<div class="weekday">{d}</div>{/each}{#each cells as cell}<div class="calendar-day" class:blank={!cell}>{#if cell}{@const forecast=days.find(d=>key(d.timestamp)===cell.key)}<span>{cell.day}</span>{#if forecast}<div class="calendar-icon"><WeatherIcon kind={forecast.icon}/></div><strong>{value(forecast.max,'°')} / {value(forecast.min,'°')}</strong><small>{value(forecast.probability,'%')} rain</small>{:else}<small class="no-data">No forecast</small>{/if}{/if}</div>{/each}</div></section>
{/if}
<style>.period-panel{background:#fffef9;border:1px solid #dce4d3;border-radius:16px;padding:24px;margin-bottom:24px}.period-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}.period-heading h2{margin:0}.period-heading label{display:grid;gap:8px;font-size:12px}.hours{display:flex;overflow-x:auto;gap:12px;padding-top:24px}.hours article{display:grid;gap:10px;min-width:135px;padding:18px;background:#f0f4e8;border-radius:12px}.hours span,.hours small{font-size:11px}.icon{width:64px;height:64px;color:#719b9f}.daily-summary{display:flex;gap:22px;margin-top:24px;padding:24px;background:#edf2e3;border-radius:12px}.daily-summary h3{text-transform:capitalize}.daily-summary p{font-size:12px;max-width:550px;margin-bottom:0}.daily-summary .icon{flex-shrink:0}.month-buttons{display:flex;gap:8px}.coverage{font-size:12px;color:#687865;margin:20px 0}.calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));border-left:1px solid #e0e6d8;border-top:1px solid #e0e6d8}.weekday,.calendar-day{border-right:1px solid #e0e6d8;border-bottom:1px solid #e0e6d8;padding:12px}.weekday{font-size:11px;background:#edf2e3}.calendar-day{min-height:120px;display:flex;flex-direction:column;gap:8px}.calendar-day>span{font-size:12px}.calendar-day strong{font-size:12px}.calendar-day small{font-size:10px;color:#687865}.calendar-icon{width:38px;height:38px;color:#719b9f}.blank{background:#f5f6ef}.no-data{margin-top:auto}.calendar-day:has(.calendar-icon){background:#f0f5e5}@media(max-width:600px){.period-panel{padding:16px}.calendar-day,.weekday{padding:5px}.calendar-day{min-height:96px;gap:5px}.calendar-day strong{font-size:9px}.calendar-day small{font-size:8px}.calendar-icon{width:26px;height:26px}.weekday{font-size:9px}.daily-summary{padding:16px;gap:12px}.daily-summary .icon{width:42px;height:42px}.month-buttons .p-button{padding:10px;font-size:11px}}</style>
